<script setup>import {ref} from 'vue';const tab=ref('basic');const form=ref({name:'Samsung 634L SpaceMax French Door Smart Refrigerator',brand:'Samsung Electronics',sku:'RS64R5304B4/TL',category:'Home Appliances / Refrigerators',description:'Engineered with SpaceMax insulation technology, dual cooling climate zones, and AI energy saving mode.',price:1499,cost:850,discount:13,stock:48,threshold:10,weight:115});const tabs=[['basic','Basic Info'],['media','Media'],['pricing','Pricing & Inventory']]</script><template><div><div class="page-head"><div><span class="eyebrow">CATALOG / INVENTORY</span><h1>{{form.name}}</h1><p>Configure product entry, warehouse logistics, and global fiscal parameters.</p></div><div><button class="button button-ghost">Discard</button><button class="button button-dark">Save as Draft</button><button class="button button-blue">Save Product</button></div></div><div class="editor-tabs"><button v-for="t in tabs" :key="t[0]" :class="{active:tab===t[0]}" @click="tab=t[0]">{{t[1]}}</button></div><section class="editor-grid"><div class="panel form-panel"><template v-if="tab==='basic'"><h2>General Information</h2><div class="form-grid"><label>Product Name *<input v-model="form.name"></label><label>Brand Name *<input v-model="form.brand"></label><label>SKU / Model Code *<input v-model="form.sku"></label><label>Category *<input v-model="form.category"></label><label class="full-field">Description<textarea v-model="form.description"></textarea></label></div><h2>Publishing</h2><label>Catalog State<select><option>Draft (Internal Only)</option><option>Published</option></select></label><div class="preview"><span class="status draft">DRAFT</span><h3>{{form.name}}</h3><p>{{form.category}}</p><strong>${{form.price}}</strong></div></template><template v-else-if="tab==='media'"><h2>Product Photos</h2><div class="dropzone">Drag & drop product photos here<br><small>PNG, JPG, WEBP · up to 10MB per image · 1:1 recommended</small></div><div class="image-list"><div v-for="n in 4" :key="n" class="image-box">VORA<br><small>Image {{n}}</small></div></div></template><template v-else><h2>Financial & Pricing Architecture</h2><div class="form-grid"><label>Price before discount<input v-model.number="form.price" type="number"></label><label>Discount %<input v-model.number="form.discount" type="number"></label><label>COGS<input v-model.number="form.cost" type="number"></label><label>Currency<select><option>USD ($)</option></select></label><label>Stock Available<input v-model.number="form.stock" type="number"></label><label>Low Stock Threshold<input v-model.number="form.threshold" type="number"></label><label>Package Weight (kg)<input v-model.number="form.weight" type="number"></label></div><div class="margin-box"><span>Estimated margin</span><b>{{(((form.price*(1-form.discount/100)-form.cost)/(form.price*(1-form.discount/100)))*100).toFixed(1)}}%</b></div></template></div><aside class="panel side-preview"><h3>Storefront Live Preview</h3><div class="preview-image"><div class="device-shape"></div></div><b>{{form.name}}</b><small>{{form.sku}}</small><strong>${{form.price.toLocaleString()}}</strong><span>In Stock: {{form.stock}}</span></aside></section></div></template>
